Structure `runCustomerErasure`:
```ts
export async function runCustomerErasure(requestId: string): Promise<void> {
  const begun = await beginErasure(requestId); // returns {merchantId, customerId} | 'completed' | undefined(not found)
  if (!begun || begun === 'completed') return;
  try {
    const targets = await collectErasureTargets(merchantId, customerId);
    await deleteCapturedEmails(targets.emails); // mailpit — code email_cleanup_failed
    await scrubStoredDocuments(merchantId, customerId, targets); // minio — storage_cleanup_failed; returns checksums
    await scrubProjections(merchantId, customerId); // redis+opensearch — projection_cleanup_failed
    await scrubDatabase(merchantId, customerId, targets, rewritten); // database_cleanup_failed
    await completeErasure(requestId);
  } catch (error) {
    await failErasure(requestId, code);
    throw error; // so worker failJob records attempt & retries
  }
}
```
Error code attribution: wrap each step; error carries `.code` property we set: `Object.assign(new Error(...), { code: 'storage_cleanup_failed' })` hmm but code on Error... define class ErasureStepError extends Error { constructor(readonly stableCode: string, cause) }. failErasure uses that code; unknown → 'erasure_processing_failed'.

