    cause: unknown,
  ) {
    super(stableCode, { cause });
  }
}

async function step<T>(stableCode: string, operation: () => Promise<T>): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    throw error instanceof ErasureStepError ? error : new ErasureStepError(stableCode, error);
