/** An erased customer keeps an anonymized tombstone row with status 'erased'. */
export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2 AND status='erased'`,
