export async function beginErasure(requestId: string): Promise<{ merchantId: string; customerId: string } | undefined> {
  return await transaction(async (client) => {
    const result = await client.query<{ merchant_id: string; customer_id: string }>(
      `UPDATE customers.erasure_requests
       SET status='processing',attempts=attempts+1,updated_at=now()
       WHERE id=$1 AND status IN ('pending','failed','processing')
       RETURNING merchant_id,customer_id`,
      [requestId],
    );
    const row = result.rows[0];
    return row ? { merchantId: row.merchant_id, customerId: row.customer_id } : undefined;
  });
}

