export async function storeCleanupTargets(requestId: string, targets: ErasureTargets): Promise<void> {
  await pool.query(
    `UPDATE customers.erasure_requests SET cleanup_targets=$2,updated_at=now()
     WHERE id=$1 AND status<>'completed'`,
    [requestId, JSON.stringify(targets)],
  );
}

export async function loadCleanupTargets(requestId: string): Promise<ErasureTargets> {
  const result = await pool.query<{ cleanup_targets: ErasureTargets | null }>(
