async function readStoredObject(objectKey: string): Promise<string | undefined> {
  try {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(chunk as Buffer);
    return Buffer.concat(chunks).toString('utf8');
  } catch (error) {
    if ((error as { code?: unknown }).code === 'NoSuchKey') return undefined;
    throw error;
  }
}

/**
 * Rewrites retained financial documents (receipts, invoices) so they keep their financial
 * meaning without identifying the customer, and removes import artifacts that mention them.
 */
export async function scrubStoredDocuments(merchantId: string, customerId: string): Promise<DocumentScrubResult> {
  const snapshot = anonymizedCustomerSnapshot(customerId);
  const rewritten: RewrittenDocument[] = [];
  const deletedImportKeys: string[] = [];

  const manifests = await pool.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests
     WHERE merchant_id=$1 AND customer_id=$2 AND document_type IN ('receipt','invoice')`,
    [merchantId, customerId],
  );
  for (const manifest of manifests.rows) {
    const content = await readStoredObject(manifest.object_key);
    if (content === undefined) continue;
    const document = JSON.parse(content) as Record<string, unknown>;
    document.customer = snapshot;
    const body = JSON.stringify(document);
    await objectStore.putObject(DOCUMENT_BUCKET, manifest.object_key, body, Buffer.byteLength(body), {
      'Content-Type': 'application/json',
    });
    rewritten.push({ objectKey: manifest.object_key, checksum: createHash('sha256').update(body).digest('hex') });
  }

  const imports = await pool.query<{ object_key: string }>(
    `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
    [merchantId],
  );
  for (const imported of imports.rows) {
    const content = await readStoredObject(imported.object_key);
    if (content === undefined || !content.includes(customerId)) continue;
    await objectStore.removeObject(DOCUMENT_BUCKET, imported.object_key);
    deletedImportKeys.push(imported.object_key);
  }

  return { rewritten, deletedImportKeys };
}

/** Removes cached and indexed customer projections. */
export async function removeCustomerProjection(redis: Redis, merchantId: string, customerId: string): Promise<void> {
  const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
  await redis.del(cacheKey, `${cacheKey}:activity`);
  try {
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` });
  } catch (error) {
    if ((error as { meta?: { statusCode?: unknown } }).meta?.statusCode !== 404) throw error;
  }
}

export async function scrubProjections(redis: Redis, merchantId: string, customerId: string): Promise<void> {
  await removeCustomerProjection(redis, merchantId, customerId);
}

