    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET status='cancelled',cancelled_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending','failed')`,
      [merchantId, customerId],
