/** Deletes already-captured provider mailboxes messages addressed to the erased customer. */
export async function deleteCapturedEmails(emails: string[]): Promise<void> {
  for (const email of emails) await deleteMailpitMessagesForRecipient(email);
}

/**
 * Runs one erasure attempt. Every step is idempotent so a retry after failure or restart
 * converges on the same result; the request is marked failed with a stable code on error.
 */
export async function runCustomerErasure(requestId: string, redis: Redis): Promise<void> {
  const begun = await beginErasure(requestId);
  if (!begun) return;
  const { merchantId, customerId } = begun;
  try {
    const collected = await step('database_cleanup_failed', () => collectErasureTargets(merchantId, customerId));
