    await step('database_cleanup_failed', () => completeErasure(requestId));
  } catch (error) {
    const stableCode = error instanceof ErasureStepError ? error.stableCode : 'erasure_processing_failed';
    await failErasure(requestId, stableCode);
    throw error;
  }
