  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

function toResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: new Date(row.created_at).toISOString(),
    updatedAt: new Date(row.updated_at).toISOString(),
    completedAt: row.completed_at ? new Date(row.completed_at).toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  /**
   * Starts or resumes the deletion workflow for a customer. Idempotency keys are scoped to
   * the merchant: replaying a key returns the original request, reusing it for a different
   * customer conflicts, and a new key for a customer with an existing request returns that
   * request instead of starting another workflow.
   */
  async request(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestResponse> {
    return await transaction(async (client) => {
      const byKey = await this.findByKey(client, merchantId, idempotencyKey);
      if (byKey && byKey.customer_id !== customerId) {
        throw Object.assign(new Error('idempotency key was used for a different customer'), { statusCode: 409 });
      }
      const existing = byKey ?? await this.findByCustomer(client, merchantId, customerId);
      if (existing) return toResponse(await this.redriveIfFailed(client, existing));
      if (!await this.customerExists(client, merchantId, customerId)) {
        throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
      }
      const created = await client.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
         VALUES($1,$2,$3)
         ON CONFLICT(merchant_id,customer_id) DO NOTHING
         RETURNING *`,
        [merchantId, customerId, idempotencyKey],
      );
      const row = created.rows[0] ?? await this.findByCustomer(client, merchantId, customerId);
      if (!row) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
      if (created.rows[0]) await this.enqueue(client, row);
      return toResponse(await this.redriveIfFailed(client, row));
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    const row = result.rows[0];
    return row ? toResponse(row) : undefined;
  }

  /** A failed request is safe to retry: reposting requeues it under the same request ID. */
  private async redriveIfFailed(client: pg.PoolClient, row: ErasureRequestRow): Promise<ErasureRequestRow> {
    if (row.status !== 'failed') return row;
    const updated = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='pending',last_error=NULL,updated_at=now()
       WHERE id=$1 AND status='failed'
       RETURNING *`,
      [row.id],
    );
    const redriven = updated.rows[0];
    if (!redriven) return row;
    await this.enqueue(client, redriven);
    return redriven;
  }

  private async enqueue(client: pg.PoolClient, row: ErasureRequestRow): Promise<void> {
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
       VALUES('privacy','erase_customer_data',$1,$2)`,
      [row.merchant_id, JSON.stringify({ requestId: row.id, merchantId: row.merchant_id, customerId: row.customer_id })],
    );
  }

  private async findByKey(client: pg.PoolClient, merchantId: string, key: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`,
      [merchantId, key],
    );
    return result.rows[0];
  }

  private async findByCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  private async customerExists(client: pg.PoolClient, merchantId: string, customerId: string): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }
}
"}

