{"command":"create","path":"/workspace/source/apps/erasure-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
} from '../../../packages/operations/src/job-lifecycle.js';
import { runCustomerErasure, type ErasureJobPayload } from '../../../packages/privacy/src/erasure.js';

process.env.SERVICE_NAME = 'erasure-worker';
const workerId = `erasure-worker-${randomUUID()}`;
const controller = new AbortController();
const redis = new Redis(config().REDIS_URL);

async function run(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases('privacy');
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>('privacy', workerId);
    if (!job) { await new Promise((resolve) => setTimeout(resolve, 250)); continue; }
    try {
      if (job.job_type === 'erase_customer_data') await runCustomerErasure(job.payload.requestId, redis);
      await transaction(async (client) => await completeJob(client, job));
    } catch (error) {
      logger.error({ error, jobId: job.id }, 'erasure job failed');
      await transaction(async (client) => await failJob(client, job, error));
    }
  }
}

void run(controller.signal);
logger.info({ workerId }, 'erasure worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => { controller.abort(); void redis.quit(); });
"}

