test('anonymized customer snapshots are deterministic and carry no personal data', () => {
  const customerId = randomUUID();
  const snapshot = anonymizedCustomerSnapshot(customerId);
  assert.deepEqual(snapshot, anonymizedCustomerSnapshot(customerId));
  assert.equal(snapshot.id, customerId);
  assert.equal(snapshot.status, 'erased');
