async function api(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}) {
  const init: RequestInit = { method, headers: { authorization: `Bearer ${apiKey}`, ...headers } };
  if (body !== undefined) { (init.headers as Record<string, string>)['content-type'] = 'application/json'; init.body = JSON.stringify(body); }
  const response = await fetch(`${gateway}${path}`, init);
  return { status: response.status, body: await response.json().catch(() => null) } as { status: number; body: any };
}

async function waitRequest(requestId: string, wanted: string[]): Promise<any> {
  for (let i = 0; i < 90; i += 1) {
    const poll = await api(`/v1/erasure-requests/${requestId}`);
    if (wanted.includes(poll.body.status)) return poll.body;
    await sleep(1000);
  }
  throw new Error(`request ${requestId} did not reach ${wanted.join('/')}`);
}

