  const erasure = await api(`/v1/customers/${c1.customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `inflight-erase-${randomUUID()}` });
  assert.equal(erasure.status, 202);
  const final = await waitRequest(erasure.body.id, ['completed', 'failed']);
  assert.equal(final.status, 'completed', JSON.stringify(final));
  await writeState({ ...c1, paymentId: payment.body.id, requestId: erasure.body.id });
