    await sleep(1000);
  }
  assert.equal(payment.status, 'succeeded', 'in-flight payment must still complete after erasure');
  assert.ok(!JSON.stringify(payment.customer_snapshot).includes(state.email), 'snapshot must be anonymized');
  const captures = await pool.query(`SELECT count(*)::int c FROM payments.captures WHERE payment_intent_id=$1 AND status='succeeded'`, [state.paymentId]);
  assert.equal(captures.rows[0].c, 1, 'capture recorded');
  const ledger = await pool.query(
    `SELECT coalesce(sum(CASE WHEN p.direction='debit' THEN p.amount ELSE -p.amount END),0)::int balance
     FROM payments.ledger_entries e JOIN payments.ledger_postings p ON p.entry_id=e.id
     WHERE e.reference_type='capture' AND e.reference_id=$1`, [state.paymentId]);
  assert.equal(ledger.rows[0].balance, 0, 'ledger balanced for the capture');
  for (let i = 0; i < 30; i += 1) {
    const manifest = await pool.query(`SELECT * FROM operations.document_manifests WHERE document_type='receipt' AND metadata->>'paymentId'=$1`, [state.paymentId]);
    if (manifest.rows[0]) break;
    await sleep(1000);
  }
  const manifest = (await pool.query(`SELECT * FROM operations.document_manifests WHERE document_type='receipt' AND metadata->>'paymentId'=$1`, [state.paymentId])).rows[0];
  assert.ok(manifest, 'receipt manifest must exist for the completed payment');
  const { Client: MinioClient } = await import('minio');
  const minio = new MinioClient({
    endPoint: process.env.MINIO_ENDPOINT!, port: Number(process.env.MINIO_PORT), useSSL: false,
    accessKey: process.env.MINIO_ACCESS_KEY!, secretKey: process.env.MINIO_SECRET_KEY!,
  });
  const stream = await minio.getObject('payflow-documents', manifest.object_key);
  const chunks: Buffer[] = [];
  for await (const chunk of stream) chunks.push(chunk as Buffer);
  const receipt = Buffer.concat(chunks).toString('utf8');
  assert.ok(!receipt.includes(state.email), 'receipt for post-erasure capture must not contain PII');
  const leaks = await pool.query(
    `SELECT count(*)::int c FROM operations.outbox_events WHERE payload::text LIKE $1`, [`%${state.email}%`]);
  assert.equal(leaks.rows[0].c, 0, 'no outbox event may carry the erased email');
